sys_script_include.script:
var ChecklistGenerator = Class.create();
ChecklistGenerator.prototype = {

    initialize: function() {},

    generateFromPolicy: function(assessmentGR) {

        if (!assessmentGR.policy)
            return;

        var existing = new GlideRecord('x_1858206_sentin_0_checklist_result');

        existing.addQuery('assessment', assessmentGR.getUniqueValue());
        existing.setLimit(1);
        existing.query();

        if (existing.hasNext()) {
            return;
        }

        var criteriaGR = new GlideRecord('x_1858206_sentin_0_policy_criteria');

        criteriaGR.addQuery('policy', assessmentGR.policy);
        criteriaGR.addQuery('active', true);
        criteriaGR.query();

        while (criteriaGR.next()) {

            var checklistGR = new GlideRecord('x_1858206_sentin_0_checklist_result');

            checklistGR.initialize();

            checklistGR.assessment = assessmentGR.sys_id;
            checklistGR.criteria = criteriaGR.sys_id;
            checklistGR.mandatory = criteriaGR.mandatory;
            checklistGR.weight = criteriaGR.weight;
            checklistGR.result = 'pending';

            checklistGR.insert();
        }
    },

    type: 'ChecklistGenerator'
};
